--
-- Name: AsinView; Type: VIEW; Schema: public; Owner: viasuser
--

CREATE VIEW public."AsinView" AS
 SELECT a.id,
    a.code AS asin,
    latest."productCodesEAN" AS ean,
    b.name AS brand,
    sel.name AS seller,
    latest."buyBoxCurrent" AS "buyBoxPrice",
    public.calculate_max_buy_price(a.id) AS "maxBuyPrice"
   FROM (((public."ASIN" a
     LEFT JOIN public."Brand" b ON ((a."brandId" = b.id)))
     LEFT JOIN LATERAL ( SELECT pf."sellerId",
            pf."buyBoxCurrent",
            pf."productCodesEAN"
           FROM public."ProductFinder" pf
          WHERE (pf."asinId" = a.id)
          ORDER BY pf."createdAt" DESC
         LIMIT 1) latest ON (true))
     LEFT JOIN public."Seller" sel ON ((latest."sellerId" = sel.id)))
  ORDER BY a.id;


