--
-- Name: WholesaleCandidatesView; Type: VIEW; Schema: public; Owner: viasuser
--

CREATE VIEW public."WholesaleCandidatesView" AS
 SELECT m.name AS manufacturer,
    b.name AS brand,
    s.name AS "sellerName",
    public.get_asin_filter_reason(a.id) AS "filterReason",
    (count(DISTINCT a.id))::integer AS "asinCount",
    string_agg(DISTINCT a.code, ', '::text) AS asins,
    string_agg(DISTINCT s."productCodesEAN", ', '::text) AS eans,
    string_agg(DISTINCT d.name, ', '::text) AS distributors,
    a."brandId",
    s."sellerId"
   FROM (((((public."ASIN" a
     JOIN public."Brand" b ON ((a."brandId" = b.id)))
     JOIN public."Manufacturer" m ON ((a."manufacturerId" = m.id)))
     LEFT JOIN LATERAL ( SELECT snap."sellerId",
            sel.name,
            snap."productCodesEAN"
           FROM (public."ProductFinder" snap
             LEFT JOIN public."Seller" sel ON ((snap."sellerId" = sel.id)))
          WHERE (snap."asinId" = a.id)
          ORDER BY snap."createdAt" DESC
         LIMIT 1) s ON (true))
     LEFT JOIN public."_ASINToDistributor" ad ON ((ad."A" = a.id)))
     LEFT JOIN public."Distributor" d ON ((ad."B" = d.id)))
  GROUP BY m.name, b.name, s.name, (public.get_asin_filter_reason(a.id)), a."brandId", s."sellerId"
  ORDER BY (public.get_asin_filter_reason(a.id)) NULLS FIRST, (count(DISTINCT a.id)) DESC;


ALTER VIEW public."WholesaleCandidatesView" OWNER TO viasuser;

